CREATE OR REPLACE VIEW public.vw_vinculos_cobertura WITH (security_invoker = true) AS SELECT s.nome_patologia, count(DISTINCT s.nome_exame) AS total_exames_vinculados, count(*) FILTER (WHERE s.obrigatoriedade = 'essencial') AS essenciais, count(*) FILTER (WHERE s.obrigatoriedade = 'recomendado') AS recomendados, count(*) FILTER (WHERE s.obrigatoriedade = 'condicional') AS condicionais, count(*) FILTER (WHERE s.obrigatoriedade = 'nao_recomendado') AS nao_recomendados FROM public.stg_patologia_exames s GROUP BY s.nome_patologia ORDER BY total_exames_vinculados DESC; CREATE OR REPLACE VIEW public.vw_vinculos_sem_conduta WITH (security_invoker = true) AS SELECT s.nome_patologia, s.nome_exame, s.finalidade, s.obrigatoriedade, s.fonte_id FROM public.stg_patologia_exames s WHERE s.conduta_se_alterado IS NULL OR s.conduta_se_alterado = '' OR s.conduta_se_alterado = 'NAO_NA_FONTE' ORDER BY s.nome_patologia; CREATE OR REPLACE VIEW public.vw_vinculos_negativos WITH (security_invoker = true) AS SELECT s.nome_patologia, s.nome_exame, s.nao_solicitar_se, s.fonte_id FROM public.stg_patologia_exames s WHERE s.obrigatoriedade = 'nao_recomendado' ORDER BY s.nome_patologia; CREATE OR REPLACE VIEW public.vw_patologias_sem_vinculo WITH (security_invoker = true) AS SELECT p.nome_patologia, p.categoria_clinica, p.is_emergencia, p.lote_id FROM public.stg_patologias p WHERE NOT EXISTS ( SELECT 1 FROM public.stg_patologia_exames pe WHERE pe.nome_patologia = p.nome_patologia ) ORDER BY p.nome_patologia; CREATE OR REPLACE VIEW public.vw_exames_sem_vinculo WITH (security_invoker = true) AS SELECT e.nome_exame, e.tipo_exame, e.categoria, e.lote_id FROM public.stg_exames e WHERE NOT EXISTS ( SELECT 1 FROM public.stg_patologia_exames pe WHERE pe.nome_exame = e.nome_exame ) ORDER BY e.nome_exame;